#!/usr/bin/env node
/*
 * Generates `src/terminal/terminal-html.ts`: one self-contained HTML document
 * with the xterm.js bundle, its stylesheet and `src/terminal/page-script.js`
 * inlined, exported as a string the WebView can be handed directly.
 *
 * The WebView has no network of its own — the daemon is reached by the RN side
 * — so nothing in the page may be loaded from a URL. Run `npm run
 * build:terminal` after bumping `@xterm/xterm` or editing the page script, and
 * commit the generated file.
 */
import { createRequire } from 'node:module'
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const require = createRequire(import.meta.url)
const projectRoot = dirname(dirname(fileURLToPath(import.meta.url)))

const xtermJs = readFileSync(require.resolve('@xterm/xterm/lib/xterm.js'), 'utf8')
const xtermCss = readFileSync(require.resolve('@xterm/xterm/css/xterm.css'), 'utf8')
const pageScript = readFileSync(join(projectRoot, 'src', 'terminal', 'page-script.js'), 'utf8')
const xtermVersion = require('@xterm/xterm/package.json').version

/*
 * user-scalable=no keeps the pane at the font size the settings ask for:
 * Decision 2 pans a source-sized pane rather than pinching it, so a stray
 * two-finger gesture must not change what the columns measure.
 */
const html = `<!doctype html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1, minimum-scale=1, user-scalable=no, viewport-fit=cover">
<title>Commando pane</title>
<style>
${xtermCss}
</style>
<style>
html, body { margin: 0; padding: 0; height: 100%; background: #232136; }
/*
 * The page is the pan surface in both directions: a source-sized pane is
 * routinely wider and taller than the phone, and xterm always paints its whole
 * grid, so the last rows are only reachable by moving pixels. xterm's own
 * viewport still owns the scrollback, and iOS chains to the page once that
 * inner scroller runs out.
 */
body { overflow: auto; -webkit-overflow-scrolling: touch; -webkit-text-size-adjust: none; -webkit-tap-highlight-color: transparent; }
/*
 * width:max-content is what makes the default (source-sized) mode work: the
 * page is as wide as the pane's own columns and WKWebView pans it sideways.
 * In "Fit to phone" the computed columns match the viewport, so nothing pans.
 */
#terminal { width: max-content; min-width: 100%; min-height: 100%; }
.xterm .xterm-viewport { overflow-y: auto; -webkit-overflow-scrolling: touch; }
</style>
</head>
<body>
<div id="terminal"></div>
<script>
${xtermJs}
</script>
<script>
${pageScript}
</script>
</body>
</html>
`

const banner = `// Generated by scripts/build-terminal-html.mjs from @xterm/xterm ${xtermVersion}
// and src/terminal/page-script.js. Do not edit by hand — run \`npm run build:terminal\`.
/* eslint-disable */
`

const output = join(projectRoot, 'src', 'terminal', 'terminal-html.ts')
mkdirSync(dirname(output), { recursive: true })
writeFileSync(
  output,
  `${banner}\nexport const XTERM_VERSION = ${JSON.stringify(xtermVersion)}\n\nexport const TERMINAL_HTML = ${JSON.stringify(html)}\n`,
)

process.stdout.write(`terminal-html.ts written (${(html.length / 1024).toFixed(0)} KiB, xterm ${xtermVersion})\n`)
